-- The tenant administrator may now export and import the DR bundle of the tenant's own SAML
-- signing keys (Authentication → SAML in the admin console). The bundle holds only that tenant's
-- keys and imports only into the tenant it was made for, so it is a tenant operation, not a
-- platform one. The permission list is the whole list of ar-lib-core's ADMIN_ROLE_DEFINITIONS for
-- ar_tenant_admin, as the baseline seeds it, with the two permissions added after retire_backup.
-- Only the canonical built-in row changes; custom roles that inherit from it see the new
-- permissions through inheritance.
UPDATE admin_roles
   SET permissions_json = '["admin:users:*", "admin:sessions:*", "admin:account_support_context:*", "admin:account_legal_holds:*", "admin:account_assurance:*", "admin:clients:*", "admin:scopes:*", "admin:roles:*", "admin:settings:read", "admin:settings:write", "admin:policy:simulate", "admin:policy:rebac:write", "admin:flows:validate", "admin:flows:compile", "admin:flows:publish", "admin:security:*", "admin:ip_allowlist:*", "admin:external_providers:*", "admin:external_token_refresh:*", "admin:directory_auth:*", "admin:saml_attribute_presets:*", "admin:saml_providers:list", "admin:saml_providers:read", "admin:saml_providers:create", "admin:saml_providers:update", "admin:saml_providers:delete", "admin:saml_providers:metadata:import", "admin:saml_providers:metadata:refresh", "admin:saml_providers:signing:publish_next", "admin:saml_providers:signing:promote", "admin:saml_providers:signing:retire_backup", "admin:saml_providers:signing:dr_bundle:export", "admin:saml_providers:signing:dr_bundle:import", "admin:webhooks:*", "admin:vc:*", "admin:auth_config_plans:*", "admin:bulk_plans:*", "admin:machine_access:*", "admin:agent_grants:*", "admin:agent_settings:*", "admin:agent_elevation:reconcile", "admin:agent_task_sets:*", "admin:agent_scope_policies:*", "admin:agent_templates:publish", "admin:agent_baselines:*", "admin:jobs:read", "admin:jobs:write", "admin:jobs:artifact:read", "admin:audit:*", "admin:admin_audit:*", "admin:operational_logs:*", "admin:logging:overview:read", "admin:logging:delivery_events:read", "admin:logging:exports:create", "admin:logging:tenant_overrides:read", "admin:logging:tenant_overrides:update", "admin:admin_logging:overview:read", "admin:admin_logging:coverage:read", "admin:admin_logging:repair:read", "admin:email_deliveries:read", "admin:email_deliveries:recipient:masked:read", "admin:email_deliveries:recipient:full:read", "admin:support_ops:registry:read", "admin:support_ops:aggregate:read", "admin:support_ops:cohorts:preview", "admin:support_ops:cohorts:create", "admin:support_ops:actions:request", "admin:support_ops:actions:read", "admin:support_ops:actions:approve", "admin:support_ops:actions:execute", "admin:approvals:read", "admin:approvals:detail:read", "admin:approvals:write", "admin:approvals:approve", "admin:approvals:grant:issue", "admin:admin_users:read", "admin:admin_users:write", "admin:admin_users:delete", "admin:admin_roles:read", "admin:admin_roles:write", "admin:admin_roles:delete"]',
       updated_at = __AUTHRIM_NOW_EPOCH_MILLISECONDS__
 WHERE id = 'role_ar_tenant_admin'
   AND tenant_id = 'default'
   AND is_system = 1
   AND permissions_json NOT LIKE '%admin:saml_providers:signing:dr_bundle:export%';
